// ═══════════════════════════════════════════════════════════════
// LOOKUP & RECHERCHE
// ═══════════════════════════════════════════════════════════════


/**
 * Lookup principal — résout un code erreur depuis le content API.
 * Essaie dans l'ordre :
 *   1. Code détaillé exact (6 chiffres ex: "010200")
 *   2. Code court exact (4 chiffres ex: "0102")
 *   3. Content + "00" suffix → 6 chiffres (ex: "0102" → "010200")
 *   4. Codes ECO/MBA/VSE/V (format long ex: "ECO001002000")
 *   5. Préfixe F pour codes numériques (ex: "F0017")
 *   6. Recherche partielle
 */
export function lookupErrorCode(content: string): S4LErrorCode | undefined {
  if (!content || content === '0000' || content === '000000') return undefined;
  const c = content.trim();

  // 1. Code détaillé 6 chiffres
  if (c in DETAIL_CODES) {
    const [desc, cause] = DETAIL_CODES[c];
    return { code: c, family: classifyFamily(c), description: desc, cause: cause || undefined };
  }

  // 2. Code court 4 chiffres
  if (c in SHORT_CODES) {
    // Chercher aussi la version détaillée pour la cause
    const detailed = DETAIL_CODES[c + '00'];
    return {
      code: c,
      family: classifyFamily(c),
      description: detailed ? detailed[0] : SHORT_CODES[c],
      cause: detailed?.[1] || undefined,
    };
  }

  // 3. Content + "00" → 6 chiffres
  if (/^\d{4}$/.test(c) && (c + '00') in DETAIL_CODES) {
    const [desc, cause] = DETAIL_CODES[c + '00'];
    return { code: c, family: classifyFamily(c), description: desc, cause: cause || undefined };
  }

  // 4. Codes longs ECO/MBA/VSE/V → extraire les 4 ou 6 chiffres centraux
  const ecoMatch = c.match(/^(?:ECO|MBA|VSE|V)(\d{3})(\d{3})(\d{3})?$/);
  if (ecoMatch) {
    const [, grp, cd, sub] = ecoMatch;
    // Essayer grp+cd (6 chiffres) puis grp+cd+sub (9 chiffres)
    const sixDigit = grp + cd;
    if (sixDigit in DETAIL_CODES) {
      const [desc, cause] = DETAIL_CODES[sixDigit];
      return { code: c, family: c.replace(/\d.*/,''), description: desc, cause: cause || undefined };
    }
    const fourDigit = grp.slice(1) + cd.slice(1);
    if (fourDigit in SHORT_CODES) {
      return { code: c, family: c.replace(/\d.*/,''), description: SHORT_CODES[fourDigit] };
    }
    // 9 chiffres
    if (sub) {
      const nineDigit = grp + cd + sub;
      if (nineDigit in DETAIL_CODES) {
        const [desc, cause] = DETAIL_CODES[nineDigit];
        return { code: c, family: c.replace(/\d.*/,''), description: desc, cause: cause || undefined };
      }
    }
  }

  // 5. Préfixe F
  if (/^F\d+$/.test(c)) {
    const num = c.slice(1);
    return lookupErrorCode(num);
  }
  if (/^\d+$/.test(c) && c.length >= 2) {
    const padded4 = c.padStart(4, '0');
    if (padded4 in SHORT_CODES) {
      const detailed = DETAIL_CODES[padded4 + '00'];
      return {
        code: c,
        family: classifyFamily(padded4),
        description: detailed ? detailed[0] : SHORT_CODES[padded4],
        cause: detailed?.[1] || undefined,
      };
    }
  }

  return undefined;
}

/** Lookup événement (SUCESO) */
export function lookupSuceso(code: string): string | undefined {
  return SUCESO_CODES[code] || SUCESO_CODES[code.padStart(4, '0')];
}

/** Lookup avertissement (AVISO) */
export function lookupAviso(code: string): string | undefined {
  return AVISO_CODES[code] || AVISO_CODES[code.padStart(8, '0')];
}

/** Classifier la famille depuis un code numérique */
function classifyFamily(code: string): string {
  const n = parseInt(code.slice(0, 2), 10);
  if (n <= 1) return 'Sécurité';
  if (n <= 3) return 'Portes';
  if (n <= 5) return 'Positionnement';
  if (n <= 7) return 'Alimentation';
  if (n <= 9) return 'Configuration';
  if (n <= 11) return 'Communication';
  if (n <= 13) return 'Variateur';
  if (n <= 17) return 'SIM/Télécom';
  if (n <= 25) return 'Module IoT';
  return 'Autre';
}

/** Recherche texte dans tous les codes (code ou description) */
export function searchErrorCodes(query: string, limit = 50): S4LErrorCode[] {
  if (!query || query.length < 2) return [];
  const q = query.toLowerCase();
  const results: S4LErrorCode[] = [];

  // Chercher dans codes courts
  for (const [code, desc] of Object.entries(SHORT_CODES)) {
    if (results.length >= limit) break;
    if (code.includes(q) || desc.toLowerCase().includes(q)) {
      const detailed = DETAIL_CODES[code + '00'];
      results.push({
        code,
        family: classifyFamily(code),
        description: detailed ? detailed[0] : desc,
        cause: detailed?.[1] || undefined,
      });
    }
  }

  // Chercher dans codes détaillés
  for (const [code, [desc, cause]] of Object.entries(DETAIL_CODES)) {
    if (results.length >= limit) break;
    // Éviter doublons avec codes courts
    if (results.some(r => code.startsWith(r.code))) continue;
    if (code.includes(q) || desc.toLowerCase().includes(q) || cause.toLowerCase().includes(q)) {
      results.push({ code, family: classifyFamily(code), description: desc, cause: cause || undefined });
    }
  }

  return results;
}

/** Tous les codes sous forme de S4LErrorCode[] */
export function getAllErrorCodes(): S4LErrorCode[] {
  const all: S4LErrorCode[] = [];
  // Codes courts
  for (const [code, desc] of Object.entries(SHORT_CODES)) {
    const detailed = DETAIL_CODES[code + '00'];
    all.push({
      code,
      family: classifyFamily(code),
      description: detailed ? detailed[0] : desc,
      cause: detailed?.[1] || undefined,
    });
  }
  // Codes détaillés non couverts par un code court
  for (const [code, [desc, cause]] of Object.entries(DETAIL_CODES)) {
    const short = code.slice(0, 4);
    if (short in SHORT_CODES) continue; // déjà couvert
    all.push({ code, family: classifyFamily(code), description: desc, cause: cause || undefined });
  }
  return all;
}

/** Par famille */
export function getErrorsByFamily(family: string): S4LErrorCode[] {
  return getAllErrorCodes().filter(e => e.family === family);
}

/** Par sévérité */
export function getErrorsBySeverity(severity: string): S4LErrorCode[] {
  return getAllErrorCodes().filter(e => e.severity === severity);
}

/** Stats */
export function getErrorStats() {
  const codes = getAllErrorCodes();
  const byFamily: Record<string, number> = {};
  const bySeverity: Record<string, number> = {};
  codes.forEach(e => {
    byFamily[e.family] = (byFamily[e.family] || 0) + 1;
    if (e.severity) bySeverity[e.severity] = (bySeverity[e.severity] || 0) + 1;
  });
  return { total: codes.length, byFamily, bySeverity };
}


// ── ENRICHISSEMENT DEPUIS API /info/errores ──

/** Structure retournée par GET /divide/info/errores */
export interface S4LApiErrorEntry {
  errorId: number;
  idEstandar: string;
  severity: number | null;
  functionalGroup: string | null;
  family: string | null;
  code: string | null;
  subcode: string | null;
  shortTextFR: string | null;
  shortTextEN: string | null;
  shortTextES: string | null;
  shortTextDE: string | null;
  fr: string | null;
  en: string | null;
  es: string | null;
  de: string | null;
  rearme: string | null;
  classificationAEvent: string | null;
  classificationBAction: string | null;
  icon: string | null;
}


/**
 * Fusionner les données API avec la base locale bundle.
 * L'API fournit les severity numériques + functionalGroup,
 * la base bundle fournit descriptions FR / causes.
 */
export function mergeApiErrors(apiErrors: S4LApiErrorEntry[]): S4LErrorCode[] {
  const base = getAllErrorCodes();
  const baseIdx = new Map<string, S4LErrorCode>();
  base.forEach(e => baseIdx.set(e.code, e));

  // Enrichir avec severity API
  const apiMap = new Map<string, S4LApiErrorEntry>();
  apiErrors.forEach(e => { if (e.idEstandar) apiMap.set(e.idEstandar, e); });

  const enriched = base.map(local => {
    const api = apiMap.get(local.code);
    if (!api) return local;
    return {
      ...local,
      severity: severityFromApi(api.severity) || local.severity,
      description: local.description || api.fr || api.shortTextFR || local.code,
    };
  });

  // Ajouter codes API absents de la base bundle
  apiErrors.forEach(api => {
    if (!api.idEstandar || baseIdx.has(api.idEstandar)) return;
    const desc = api.fr || api.shortTextFR || api.en || api.shortTextEN || api.idEstandar;
    if (!desc) return;
    enriched.push({
      code: api.idEstandar,
      family: api.family || api.idEstandar.replace(/\d.*/,'') || 'Autre',
      description: desc,
      severity: severityFromApi(api.severity),
    });
  });

  return enriched;
}

/** Nombre total de codes dans l'API */
export function getApiErrorCount(apiErrors: S4LApiErrorEntry[]): number {
  return apiErrors.length;
}
